/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isGridAlignment = require( '@stdlib/plot/vega/base/assert/is-grid-alignment' );
var isObject = require( '@stdlib/assert/is-object' );
var join = require( '@stdlib/array/base/join' );
var gridAlignments = require( '@stdlib/plot/vega/base/grid-alignments' );
var format = require( '@stdlib/string/format' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:layout:set:'+prop.name );


// MAIN //

/**
* Sets the grid alignment to apply to rows and columns.
*
* @private
* @param {(string|Object)} value - input value
* @throws {TypeError} must be a grid alignment or an object
* @returns {void}
*/
function set( value ) {
	if ( !isGridAlignment( value ) && !isObject( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s", or an object. Value: `%s`.', prop.name, join( gridAlignments(), '", "' ), value ) );
	}
	if ( value !== this[ prop.private ] ) {
		debug( 'Current value: %s. New value: %s.', JSON.stringify( this[ prop.private ] ), JSON.stringify( value ) );
		this[ prop.private ] = value;
		this.emit( 'change', changeEvent( prop.name ) );
	}
}


// EXPORTS //

module.exports = set;
